<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\Tenant\Domain\ValueObject\Accessor\TenantDomainAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantDomainAccessor trait.
 *
 * Covers null default, string/VO assignment via withDomain,
 * getDomain/domain accessors, and isDomainChanged with/without original.
 */
class TenantDomainAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withDomain creates a new instance with the Domain set
     * from a string value, and getDomain returns the primitive string.
     */
    public function testWithDomainFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantDomainAccessorUnitTest();

        // Act
        $result = $holder->withDomain('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getDomain());
    }
    /**
     * Asserts that withdomain has access to the value object
     * from a string value, and getDomain returns the primitive string.
     */
    public function testWithDomainFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantDomainAccessorUnitTest();

        // Act
        $result = $holder->withDomain('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->domain()->value());
    }
    public function testChangedDomain(): void
    {
        // Arrange
        $holder = new ImplWithTenantDomainAccessorUnitTest()->withDomain('one');
        $original = $holder->withDomain('one');
        $same = $holder->withDomain('one');
        $modified = $holder->withDomain('other');

        // Act
        $withSame = $original->isDomainChanged($same);
        $withDiferent = $original->isDomainChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantDomainAccessorUnitTest
{
    use TenantDomainAccessor;
}
